def withdraw(balance, amount):
    if amount <= 0:
        raise ValueError("Ashish: withdrawal amount must be positive")
    if amount > balance:
        raise RuntimeError("Ashish: insufficient funds")
    return balance - amount

try:
    print(withdraw(500, 700))
except (ValueError, RuntimeError) as e:
    print(f"Transaction rejected: {e}")
